mapper.select:
SELECT p.person_id AS personId, p.person_name AS personName, p.mobile AS mobile, p.person_code AS personCode, p.job_title AS jobTitle, p.post_id AS postId, pos.post_name AS postName, p.org_id AS orgId, org.org_name AS orgName, p.account_id AS accountId, acc.account_name AS accountName FROM exp_person p LEFT JOIN exp_org_unit org ON p.org_id = org.org_id LEFT JOIN exp_post pos ON p.post_id = pos.post_id LEFT JOIN exp_account acc ON p.account_id = acc.account_id
1=1
AND p.person_code = #{queryParam.personCode}
AND p.person_name LIKE CONCAT('%', #{queryParam.name}, '%')
AND p.mobile = #{queryParam.phone}
ORDER BY p.status,p.created_time DESC
